-- تاج الملوك V5 / شغّل الملف مرة واحدة في Supabase SQL Editor
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, public_id bigint generated by default as identity (start with 1000), display_name text not null, email text not null, role text not null default 'user' check(role in('user','admin')), account_status text not null default 'active' check(account_status in('active','restricted','banned')), code_status text not null default 'لا يوجد', created_at timestamptz not null default now(), unique(public_id));
create table if not exists public.subscription_codes(id uuid primary key default gen_random_uuid(),code text not null unique,code_type text not null check(code_type in('trial','basic')),duration_minutes int not null check(duration_minutes>0),created_by uuid references auth.users(id),created_at timestamptz not null default now(),used_by uuid references auth.users(id),activated_at timestamptz,expires_at timestamptz,disabled boolean not null default false);
create table if not exists public.guest_sessions(guest_id text primary key,last_seen timestamptz not null default now(),blocked boolean not null default false);
create table if not exists public.support_messages(id bigint generated always as identity primary key,user_id uuid references auth.users(id),guest_id text,sender_name text,body text not null,created_at timestamptz not null default now(),reply text,replied_at timestamptz);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,display_name,email) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),'عضو تاج الملوك'),coalesce(new.email,'')); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create or replace view public.my_subscription with (security_invoker=true) as select code,code_type,activated_at,expires_at from subscription_codes where used_by=auth.uid() order by activated_at desc limit 1;
create or replace function public.activate_subscription_code(p_code text) returns jsonb language plpgsql security definer set search_path=public as $$ declare c subscription_codes; existing subscription_codes; begin if auth.uid() is null then raise exception 'login required'; end if; select * into existing from subscription_codes where used_by=auth.uid() and expires_at>now() and not disabled limit 1; if found then return jsonb_build_object('ok',false,'message','يوجد كود مفعّل بالفعل'); end if; select * into c from subscription_codes where upper(code)=upper(trim(p_code)) for update; if not found or c.disabled or c.used_by is not null then return jsonb_build_object('ok',false,'message','الكود غير صالح أو مستخدم'); end if; update subscription_codes set used_by=auth.uid(),activated_at=now(),expires_at=now()+make_interval(mins=>c.duration_minutes) where id=c.id; update profiles set code_status='مفعّل' where id=auth.uid(); return jsonb_build_object('ok',true,'message','تم تفعيل الكود','expires_at',now()+make_interval(mins=>c.duration_minutes)); end $$;
create or replace function public.admin_generate_code(p_type text,p_duration_minutes int) returns text language plpgsql security definer set search_path=public as $$ declare x text; begin if not is_admin() then raise exception 'admin only'; end if; if p_type not in('trial','basic') or p_duration_minutes<1 then raise exception 'invalid'; end if; x='TAJ-'||upper(substr(encode(gen_random_bytes(8),'hex'),1,12)); insert into subscription_codes(code,code_type,duration_minutes,created_by) values(x,p_type,p_duration_minutes,auth.uid()); return x; end $$;
create or replace function public.admin_set_account_status(p_user uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not is_admin() then raise exception 'admin only'; end if; if p_status not in('active','restricted','banned') then raise exception 'invalid'; end if; update profiles set account_status=p_status where id=p_user and role<>'admin'; end $$;
alter table profiles enable row level security; alter table subscription_codes enable row level security; alter table guest_sessions enable row level security; alter table support_messages enable row level security;
drop policy if exists profile_self on profiles; create policy profile_self on profiles for select to authenticated using(id=auth.uid() or is_admin());
drop policy if exists admin_profiles on profiles; create policy admin_profiles on profiles for all to authenticated using(is_admin()) with check(is_admin());
drop policy if exists codes_admin on subscription_codes; create policy codes_admin on subscription_codes for all to authenticated using(is_admin()) with check(is_admin());
drop policy if exists code_self on subscription_codes; create policy code_self on subscription_codes for select to authenticated using(used_by=auth.uid());
drop policy if exists guests_insert on guest_sessions; create policy guests_insert on guest_sessions for insert to anon,authenticated with check(true);
drop policy if exists guests_update on guest_sessions; create policy guests_update on guest_sessions for update to anon,authenticated using(true) with check(true);
drop policy if exists guests_admin on guest_sessions; create policy guests_admin on guest_sessions for select to authenticated using(is_admin());
drop policy if exists msg_insert on support_messages; create policy msg_insert on support_messages for insert to anon,authenticated with check((auth.uid() is null and user_id is null) or user_id=auth.uid());
drop policy if exists msg_self on support_messages; create policy msg_self on support_messages for select to authenticated using(user_id=auth.uid() or is_admin());
drop policy if exists msg_admin on support_messages; create policy msg_admin on support_messages for update to authenticated using(is_admin()) with check(is_admin());
grant execute on function activate_subscription_code(text) to authenticated; grant execute on function admin_generate_code(text,int) to authenticated; grant execute on function admin_set_account_status(uuid,text) to authenticated;
